selector_to_html = {"a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5982\u4f55\u9605\u8bfb\u672c\u77e9\u9635<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u8fd9\u91cc\u7684\u8bc4\u7ea7\u63cf\u8ff0\u7684\u662f\u5e73\u53f0\uff0c\u800c\u4e0d\u662f\u67d0\u6b21\u6784\u5efa\u3002\u4ec5\u7f16\u8bd1\u4e86\u90e8\u5206\u5185\u6838\u96c6\u5408\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_BUILD_*</span></code>\uff09\u7684 wheel \u53ea\u652f\u6301\u8be5\u5e73\u53f0\u80fd\u529b\u7684\u4e00\u4e2a\u5b50\u96c6 \u2014\u2014 \u5bf9\u8be5 wheel \u800c\u8a00\uff0c\u5176\u81ea\u8eab\u7684\u6784\u5efa\u8bb0\u5f55\u624d\u662f\u6743\u5a01\u4f9d\u636e\u3002</p>", "a[href=\"#aten\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">ATen \u6b21\u7248\u672c\u7ebf\u56fa\u5b9a<a class=\"headerlink\" href=\"#aten\" title=\"Link to this heading\">#</a></h3><p>PyTorch-Plugin-FL \u4f1a\u4e3a PyTorch \u5185\u90e8\u7684 ATen \u7b97\u5b50\u6ce8\u518c\u8868\u751f\u6210\u539f\u751f\u7ed1\u5b9a\u3002\u8fd9\u4e9b\u7ed1\u5b9a\u5bf9 C++ ABI \u4e0e\u7b97\u5b50 schema \u53d8\u5316\u654f\u611f\uff0c\u56e0\u6b64\u9879\u76ee\u56fa\u5b9a\u5728\u67d0\u4e2a PyTorch \u6b21\u7248\u672c\u7ebf\u4e0a \u2014\u2014 \u5f53\u524d\u4e3a <strong>2.10.x</strong>\u3002\u4f7f\u7528\u4e0d\u540c\u7684\u6b21\u7248\u672c\uff08\u4f8b\u5982 2.11.x\uff09\u4f1a\u5bfc\u81f4\u6784\u5efa\u6216\u8fd0\u884c\u5931\u8d25\uff1b\u540c\u4e00\u6b21\u7248\u672c\u7ebf\u5185\u7684\u8865\u4e01\u7248\u672c\uff082.10.0 \u2192 2.10.1\uff09\u4e92\u76f8\u517c\u5bb9\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5e73\u53f0\u77e9\u9635<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u517c\u5bb9\u6027\u4e0e\u5e73\u53f0\u652f\u6301<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u72b6\u6001\u5b9a\u4e49<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler \u96c6\u6210<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> \u901a\u8fc7\u7f16\u8bd1\u8fdb wheel \u7684\u8bbe\u5907\u8ffd\u8e2a\u5668\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> \u4ea7\u51fa\u7684 trace \u4e0e\u540c\u4e00\u5de5\u4f5c\u8d1f\u8f7d\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code> \u4e0a\u7684 trace \u7ed3\u6784\u7b49\u4ef7\uff1a</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u72b6\u6001\u5b9a\u4e49<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile \u96c6\u6210<a class=\"headerlink\" href=\"#torch-compile\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code>\uff0c\u53ef\u5b9e\u73b0\u81ea\u52a8\u5185\u6838\u878d\u5408\u5e76\u964d\u4f4e\u8c03\u5ea6\u5f00\u9500\u3002\u8ba1\u7b97\u56fe\u59cb\u7ec8\u7559\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u4e0a\uff1a\u4e0d\u5b58\u5728\u8bbe\u5907\u5f80\u8fd4\uff0c\u4e5f\u6ca1\u6709\u56fe\u8fb9\u754c\u5904\u7684\u62f7\u8d1d\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9879\u76ee\u517c\u5bb9\u6027<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><h3>ATen \u6b21\u7248\u672c\u7ebf\u56fa\u5b9a<a class=\"headerlink\" href=\"#aten\" title=\"Link to this heading\">#</a></h3><p>PyTorch-Plugin-FL \u4f1a\u4e3a PyTorch \u5185\u90e8\u7684 ATen \u7b97\u5b50\u6ce8\u518c\u8868\u751f\u6210\u539f\u751f\u7ed1\u5b9a\u3002\u8fd9\u4e9b\u7ed1\u5b9a\u5bf9 C++ ABI \u4e0e\u7b97\u5b50 schema \u53d8\u5316\u654f\u611f\uff0c\u56e0\u6b64\u9879\u76ee\u56fa\u5b9a\u5728\u67d0\u4e2a PyTorch \u6b21\u7248\u672c\u7ebf\u4e0a \u2014\u2014 \u5f53\u524d\u4e3a <strong>2.10.x</strong>\u3002\u4f7f\u7528\u4e0d\u540c\u7684\u6b21\u7248\u672c\uff08\u4f8b\u5982 2.11.x\uff09\u4f1a\u5bfc\u81f4\u6784\u5efa\u6216\u8fd0\u884c\u5931\u8d25\uff1b\u540c\u4e00\u6b21\u7248\u672c\u7ebf\u5185\u7684\u8865\u4e01\u7248\u672c\uff082.10.0 \u2192 2.10.1\uff09\u4e92\u76f8\u517c\u5bb9\u3002</p>", "a[href=\"../architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5206\u5e03\u5f0f\u96c6\u5408\u901a\u4fe1<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>PyTorch-Plugin-FL \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code> \u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u63d0\u4f9b\u5206\u5e03\u5f0f\u652f\u6301\u3002\u5b83\u662f\u539f\u751f\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> \u5b50\u7c7b\uff0c\u5728\u5bfc\u5165\u65f6\u5b8c\u6210\u6ce8\u518c\uff0c\u56e0\u6b64 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> \u53ef\u76f4\u63a5\u4f7f\u7528\uff0c\u65e0\u9700\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> \u505a\u4efb\u4f55 monkeypatch\u3002</p>", "a[href=\"#wheel\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">wheel \u517c\u5bb9\u6027\u8bb0\u5f55<a class=\"headerlink\" href=\"#wheel\" title=\"Link to this heading\">#</a></h3><p>\u6bcf\u4e2a\u6784\u5efa\u51fa\u7684 wheel \u90fd\u5e26\u6709 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/compatibility.json</span></code>\uff0c\u5176\u4e2d\u8bb0\u5f55\u6240\u9009\u7684\u5e73\u53f0\u4e0e\u5185\u6838\u96c6\u5408\u3001\u6253\u5305\u7684 libtorch \u4f4d\u7f6e\u3001\u6784\u5efa\u671f PyTorch \u7248\u672c\u4e0e C++ ABI \u6807\u8bb0\u3001\u6784\u5efa\u65f6\u89c2\u6d4b\u5230\u7684 FlagTree/FlagGems/FlagCX \u7248\u672c\u3001\u5728\u7531\u5382\u5546\u63d0\u4f9b\u8bbe\u5907\u5e93\u65f6\u663e\u5f0f\u58f0\u660e\u7684\u5382\u5546 PyTorch \u7248\u672c\uff0c\u4ee5\u53ca wheel \u7684 Python \u4f9d\u8d56\u8981\u6c42\u3002\u53ea\u6709\u5f53\u6784\u5efa\u8005\u628a <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_SDK_VERSION</span></code> \u8bbe\u4e3a\u5df2\u9a8c\u8bc1\u503c\u65f6\u624d\u8bb0\u5f55 SDK \u7248\u672c\uff1b\u7f3a\u5931\u8868\u793a<strong>\u672a\u77e5</strong>\uff0c\u800c\u4e0d\u662f\u300c\u517c\u5bb9\u6240\u6709 SDK\u300d\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
